import { defineStore } from 'pinia';
import { getOptionFlterSection } from '@/services/apiClient.js';

//  не изменяемое поле вид
// если чекбокс существует то изменяемое
export const useFilterOptionTable = defineStore('useFilterOptionTable', {
  state: () => ({
    itemRow: [
      {
        id: {
          value: '7878',
          type: 'text',
          contenteditable: false,
        },
        sort: { value: '500', type: 'text', contenteditable: false },
        link: {
          value: '/auto/',
          type: 'link',
        },
        H1: {
          value: 'Aвто с пробегом в [локация, род.] ',
          type: 'text',
          contenteditable: false,
        },
        Title: {
          value: 'Купить авто с пробегом в [локация, род.] ',
          type: 'text',
          contenteditable: false,
        },
        Description: {
          value:
            'Авто с пробегом в [локация, род.] по низкой цене от владельцев',
          type: 'text',
          contenteditable: false,
        },
        Keywords: {
          value:
            'купить авто, купить автомобиль, продать машину, доска объявлений, перекупы, подержаные авто, новые автомобили',
          type: 'text',
          contenteditable: false,
        },
        Noindex: { value: 'нет', type: 'text', contenteditable: false },
        Город: {
          value: 'Комсомольск-на-Амуре',
          type: 'text',
          contenteditable: false,
        },
        option: { slot: 'end', contenteditable: false, id: 1 },
      },
    ],
    headerRows: [
      {
        name: 'Акт',
        width: '24px',
        helper: false,
      },
      {
        name: 'Значение (авто)',
        helper: false,
        width: '95px',
      },
      {
        name: 'Значение (вручную)',
        helper: false,
        width: '180px',
      },
      {
        name: '№ в фильтре',
        helper: false,
        width: '80px',
      },
      {
        name: 'ЧПУ',
        helper: false,
        width: '27px',
      },
      {
        name: 'ЧПУ (авто)',
        helper: false,
        width: '70px',
      },
      {
        name: 'ЧПУ (вручную)',
        helper: false,
        width: '90px',
      },
      {
        name: '№ в URL',
        helper: false,
        width: '65px',
      },
    ],
    pagination: { currentPage: 0, perPage: 0, totalPages: 0 },
  }),

  actions: {
    async getFilterItem(params) {
      const data = await getOptionFlterSection(params);
      console.log(data);
      this.pagination.currentPage = data.current_page;
      this.pagination.perPage = data.count_on_page;
      this.pagination.totalPages = data.total_count;
      this.data = data;
      this.itemRow = data.data.map((item) => ({
        act: {
          value: !!item.is_active,
          type: 'checkbox',
          contenteditable: false,
          id: item.id,
        },
        MarkAvto: {
          value: item.title || '',
          type: 'text',
          contenteditable: false,
        },
        Marсk: {
          value: item.title_manual_generate || '',
          type: 'input',
        },
        filterNumber: {
          value: item.number_in_filter || '',
          type: 'input',
        },
        CNC: {
          value: !!item.is_cnc,
          type: 'checkbox',
        },
        CNCAuto: {
          value: item.cnc_auto || '',
          type: 'text',
        },
        chpuManual: {
          value: item.cnc_manual_generate || '',
          type: 'input',
        },
        numberUrl: {
          value: item.number_in_url || '',
          type: 'input',
        },
      }));
    },

    //  siteMapInfoErrorFetch(){
    //  }
  },

  getters: {
    getPagination: (state) => state.pagination,
    getHeaderRow: (state) => state.headerRows,
    getItemRow: (state) => state.itemRow,
  },
});
