<template>
  <div class="optimization">
    <OptimizationHeader :title="title" :name="name" :status="status" />
    <div class="option-box">
      <OptimizationReturn title="Настройка значений фильтра “Марка”" />
      <div class="optimization-table__box">
        <CustomTable
          :ItemRows="itemRow"
          :headerRows="headerRows"
          :tablePagination="showPagination"
          @slot-clicked="handleButtonClick"
          @item-action="tableAction"
          :currentPage="pagination.currentPage"
          :perPage="pagination.perPage"
          :total="pagination.totalPages"
          @update:currentPage="(val) => handlePageChange(val)"
        />
        <div class="optimization__btn-box" v-if="!showPagination">
          <ButtonUI text="Сохранить изменения" @action="saveTable" />
          <ButtonUI
            text="Сброс"
            buttonClass="btn--second"
            @action="resetValue"
          />
        </div>
      </div>
    </div>
    <CustomPopUP
      v-if="isChangeMenu"
      name="Change"
      :data="itemList"
      @closing="resetValue()"
      @submit-action="popUpAction"
    />
  </div>
</template>

<script setup>
import { ref, onMounted } from 'vue';
import OptimizationHeader from '@/components/SEO/OptimizationHeader';
import OptimizationReturn from '@/components/SEO/OptimizationReturn';
import CustomTable from '@/components/UI/CustomTable';
import ButtonUI from '@/components/UI/ButtonUI';

import { useRoute } from 'vue-router';
import { isEqual, cloneDeep } from 'lodash';
import { useFilterOptionTable } from '@/store/Table/filterOptionTable.js';
import { useQueryParams } from '@/composables/useQueryParams';
import { updateFilterOption } from '@/services/apiClient.js';
import CustomPopUP from '@/components/POPUP/PopUp';

const title = ref('Фильтры');
const name = ref('Иван Иванов');
const status = ref('сейчас на странице');
const areEqual = ref(false);
const showPagination = ref(true);
const route = useRoute();
const isChangeMenu = ref(false);

const filterOptionTable = useFilterOptionTable();

const pagination = ref({
  currentPage: 1,
  perPage: 1,
  totalPages: 1,
});
const itemList = ref({});

const oldModel = ref([]);
const itemRow = ref([]);
const newRow = ref([]);
const headerRows = ref([]);

const sectionId = route.query.section_id;
const id = route.query.filter_id;

const tableAction = () => {
  newRow.value = [];
  getChangedEntities(itemRow.value, oldModel.value);
  areEqual.value = newRow.value.length === 0;
  showPagination.value = areEqual.value;
};

const getChangedEntities = (currentItems, oldItems) => {
  newRow.value = [];
  new Promise((resolve) => setTimeout(resolve, 50));
  for (let i = 0; i < currentItems.length; i++) {
    if (!isEqual(currentItems[i], oldItems[i])) {
      newRow.value.push(currentItems[i]);
    }
  }
};

const convertBack = (items) => {
  return items.map((item) => ({
    section_id: sectionId,
    filter_id: id,
    id: item.act.id,
    is_active: item?.act?.value ? 1 : 0,
    title_manual_generate: item.Marсk?.value,
    is_cnc: item.CNC?.value ? 1 : 0,
    cnc_manual_generate: item.chpuManual?.value,
    number_in_filter: +item.filterNumber?.value,
    number_in_url: +item.numberUrl?.value,
  }));
};
const popUpAction = async (item) => {
  const json = ref({});

  json.value.ids = item.items.map((el, index) => ({
    title: el.title,
    section_id: +el.section.id,
    id: +el.id,
    is_active: el.is_active,
    view_id: el.id,
    is_cnc: el.is_cnc ? 1 : 0,
    is_multiplier: el.is_multiplier,
    is_no_index: el.is_no_index,
    title_url: el?.title_url,
    is_url: el.is_url,
    number_in_filter: +el.number_in_filter,
    number_in_url: item.data[index].newPosition.value.code,
  }));
  updateQueryParams();
  getItemRow();
  json.value.is_finished = 0;
  const data = await updateFilterOption(json.value);
  if (data) {
    newRow.value = [];
    oldModel.value = cloneDeep(itemRow.value);
    areEqual.value = true;
    showPagination.value = true;
    isChangeMenu.value = false;
  }
};
const saveTable = async () => {
  const json = convertBack(newRow.value);
  const data = await updateFilterOption(json);
  // После сохранения обновляем oldModel

  if (data.success) {
    newRow.value = [];
    oldModel.value = cloneDeep(itemRow.value);
    areEqual.value = true;
    showPagination.value = true;
  } else {
    isChangeMenu.value = true;
    itemList.value.newUrl = data.new_url;
    itemList.value.oldUrl = data.old_url;
    itemList.value.message = data.message;
    itemList.value.error = data.error;
    itemList.value.items = data.recurring_positions;
    itemList.value.data = data.recurring_positions.map((el) => {
      return {
        filter: {
          value: el.title,
          type: 'text',
        },
        oldPosition: {
          value: el.number_in_url,
          type: 'text',
          contenteditable: false,
        },
        newPosition: {
          value: {
            name: el.number_in_url,
            code: el.number_in_url,
          },
          type: 'select',
          options: data.available_url_numbers.map((el) => {
            return {
              name: el,
              code: el,
            };
          }),
          contenteditable: false,
        },
      };
    });
  }
};
const resetValue = () => {
  itemRow.value = cloneDeep(oldModel.value);
  tableAction();
};
const handlePageChange = (newPage) => {
  pagination.value.currentPage = newPage;
  queryParams.value.page = newPage;
  updateQueryParams();
  getItemRow();
};
const getHeaderRow = () => {
  headerRows.value = filterOptionTable.getHeaderRow;
};
const getItemRow = async () => {
  updateQueryParams();
  await filterOptionTable.getFilterItem(buildQueryString(queryParams.value));
  itemRow.value = filterOptionTable.getItemRow;
  oldModel.value = cloneDeep(filterOptionTable.getItemRow);
  pagination.value = filterOptionTable.getPagination;
};

const {
  queryParams,
  loadQueryParamsFromRoute,
  updateQueryParams,
  buildQueryString,
} = useQueryParams();

const getParametrQRL = async () => {
  loadQueryParamsFromRoute();
};
onMounted(() => {
  getHeaderRow();
  getParametrQRL();
  getItemRow();
  loadQueryParamsFromRoute();
});
</script>

<style scoped lang="scss">
.option-box {
  height: calc(100vh - 115px);
  box-shadow: 1px 1px 6px rgba(0, 0, 0, 0.14);
  border-radius: 4px;
  padding: 12px 24px;
}
.optimization {
  margin: 16px 24px 16px 16px;
  width: calc(100% - 50px);
  display: flex;
  flex-direction: column;
  margin: 0;

  @media (max-width: 1024px) {
    justify-content: space-between;
    height: calc(100vh - 60px);
    margin-top: 85px;
  }
  &__header {
    margin-bottom: 20px;
  }
  &-table__box {
    height: calc(100% - 50px);
    display: flex;
    flex-direction: column;
    justify-content: space-between;
  }
  &-option {
    display: flex;
    justify-content: space-around;
    border-radius: 4px;
    background-color: #eef9ff;
    margin: 24px 0;
    padding: 12px 24px;
    &__box {
      display: flex;
      flex-direction: column;
      width: 100%;
    }
    &__item {
      display: flex;
      align-items: center;
      margin-bottom: 16px;
      &:first-child {
        justify-content: space-between;
      }
    }
    &__text-box {
      display: flex;
    }
    &__text {
      color: #787878;
      font-weight: 400;
      font-size: 14px;
      min-width: 150px;
    }
  }
  &__btn-box {
    display: flex;
    align-items: center;
    gap: 24px;
  }
}
</style>
